use serde::{Deserialize,Serialize}; use super::{digest,error::{AdmissionError,AdmissionErrorKind,Result},subject::SubjectId};
#[derive(Clone,Debug,Serialize,Deserialize,PartialEq,Eq)] pub enum EvidenceKind{Observation,Test,Proof,Benchmark,Receipt,Counterexample}
#[derive(Clone,Debug,Serialize,Deserialize)] pub struct Evidence{pub id:String,pub subject:SubjectId,pub kind:EvidenceKind,pub claim:String,pub payload_digest:String,pub producer:String,pub epoch:u64}
impl Evidence{pub fn validate(&self)->Result<()>{self.subject.validate()?;if self.id.is_empty()||self.claim.trim().is_empty()||self.payload_digest.len()<8{return Err(AdmissionError::new(AdmissionErrorKind::EvidenceMissing,"evidence.invalid","evidence id, claim, and payload digest are required").subject(self.subject.key()))}Ok(())}pub fn identity(&self)->String{digest::digest(&[&self.id,&self.subject.key(),&self.claim,&self.payload_digest,&self.epoch.to_string()])}}
#[derive(Clone,Debug,Default,Serialize,Deserialize)] pub struct EvidenceSet{pub items:Vec<Evidence>} impl EvidenceSet{pub fn for_subject<'a>(&'a self,s:&SubjectId)->Vec<&'a Evidence>{self.items.iter().filter(|e|e.subject.exact_match(s)).collect()}pub fn has_claim(&self,s:&SubjectId,c:&str)->bool{self.items.iter().any(|e|e.subject.exact_match(s)&&e.claim==c)}pub fn validate(&self)->Result<()>{for e in &self.items{e.validate()?}Ok(())}}